#include "engine.hpp"
// reactor-guided: случайный генератор с расчётом теплового баланса. Попытки gdTrials, предел топливных клеток gdMaxF, seed gdSeed.
int main(int argc,char**argv){int trials=(int)PI("gdTrials");int max_rods=(int)PI("gdMaxF");if(max_rods<1||max_rods>30)return 4;loadFuels();rng.seed((unsigned)PI("gdSeed"));double budget=PR.budget,venting=PR.av;for(int i=0;i<N;i++){if(i%19)a[i].push_back(i-1);if(i%19<18)a[i].push_back(i+1);if(i>=19)a[i].push_back(i-19);if(i<285)a[i].push_back(i+19);}
 long built=0,thermal=0,passed=0;double best=-1e99;ofstream log("results.csv");log<<"attempt,fuel_count,heat_B,cooling_B,worst_vent_load_B,vent_capacity_B,cost_Qa,status,net_B,reason,tick\n";
 for(int z=0;z<trials;z++){if(z&&z%2000==0)cerr<<"попыток "<<z<<" прошли "<<passed<<"\n";string g(N,'K');int nf=1+rng()%max_rods;double fc=0;for(int j=0;j<nf;j++){int i=rng()%N;if(g[i]!='K'){j--;continue;}g[i]=pickRod();fc+=fuels[g[i]].cost;}if(fc+venting>budget)continue;for(int i=0;i<N;i++)if(cores(g[i]))for(int j:a[i])if(g[j]=='K')g[j]='R';double heat=0;for(int i=0;i<N;i++)if(int c=cores(g[i])){int pulse=fuels[g[i]].pulse;for(int j:a[i])pulse+=cores(g[j]);heat+=fuels[g[i]].heat*pulse*pulse/c;}
 int pn=max(1,(int)ceil(heat/M.hullPer))+rng()%5;if(pn>count(g.begin(),g.end(),'K'))continue;for(int j=0;j<pn;j++){int i=rng()%N;if(g[i]!='K'){j--;continue;}g[i]='P';}bool viable=false;double cooling=0,worst=0,vc=0,cost=0;
 for(int step=0;step<60;step++){vector<int> places;for(int i=0;i<N;i++)if(g[i]=='K'){int fresh=0,shared=0;for(int j:a[i]){fresh+=g[j]=='K';shared+=g[j]=='V';}if(fresh&&shared==0)places.push_back(i);}if(places.empty())break;int i=places[rng()%places.size()];g[i]='O';for(int j:a[i])if(g[j]=='K')g[j]='V';array<int,128>n{};for(char c:g)n[c]++;int k=n['K'],v=n['V'];double vr=M.vr0*(1+M.ventBoost*(M.bAv+1)*k),rate=M.rate0*M.bEx*2*(1+M.capBoost*k);vc=M.vc0*(1+M.sinkBoost*M.bHs*n['P']);cooling=v*vr;
 int edges=0,maxdegree=0,active=0;for(int j=0;j<N;j++)if(g[j]=='V'){int d=0;for(int q:a[j])d+=g[q]=='O';edges+=d;maxdegree=max(maxdegree,d);active+=d>0;}worst=edges?heat*maxdegree/edges:1e99;
 // A generated outlet has only vents as heat-absorbing neighbors. No vent shared between outlets in this routing policy.
 cost=fc+venting+PR.parts(n);
 if(cost<=budget&&active*vr>=heat*1.02&&worst<=vr&&edges*rate>=heat){viable=true;if(rng()%3==0)break;}}
 built++;if(!viable)continue;
 // Re-evaluate the final field: later additions may lower K and invalidate an earlier feasible state.
 array<int,128>n{};for(char c:g)n[c]++;double vr=M.vr0*(1+M.ventBoost*(M.bAv+1)*n['K']);int edges=0,md=0;for(int i=0;i<N;i++)if(g[i]=='V'){int d=0;for(int j:a[i])d+=g[j]=='O';edges+=d;md=max(md,d);}worst=edges?heat*md/edges:1e99;cooling=n['V']*vr;if(cooling<heat*1.02||worst>vr||cost>budget)continue;thermal++;auto r=test(g,0);if(r.ok){auto q=test(g,1);if(!q.ok)r=q;else r.net=min(r.net,q.net);}log<<z<<','<<nf<<','<<heat<<','<<cooling<<','<<worst<<','<<vc<<','<<cost<<','<<r.ok<<','<<r.net<<','<<r.reason<<','<<r.tick<<'\n';if(!r.ok)continue;passed++;if(r.net>best){best=r.net;ofstream out("best.txt");out<<setprecision(12)<<"net_B "<<best<<" cost_Qa "<<cost<<" heat_B "<<heat<<" cooling_B "<<cooling<<" attempt "<<z<<'\n';for(int y=0;y<16;y++)out<<g.substr(y*19,19)<<'\n';
  ofstream c2("cand-"+to_string(passed%50)+".txt");c2<<"1 0 0 0 1 0 0 0 0 "<<z<<'\n';for(int y=0;y<16;y++)c2<<g.substr(y*19,19)<<'\n';}}
 ofstream st("stats.txt");st<<"attempts "<<trials<<" constructed "<<built<<" thermal_screen_pass "<<thermal<<" simulated_pass "<<passed<<" best_net_B "<<best<<'\n';cout<<"done "<<trials<<' '<<thermal<<' '<<passed<<' '<<best<<'\n';return 0;}
